32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioResult {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUM_RATES: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const COMPONENT_BLOCK_SIZE = 3;
55	const COMPONENT_BLOCK_PREMIUM = 60;
56	
57	const countByType = (items: Item[]): Map<string, number> =>
58	  items.reduce(
59	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
60	    new Map<string, number>(),
61	  );
62	
63	const basePremiumForType = (type: string, count: number): number =>
64	  count === COMPONENT_BLOCK_SIZE
65	    ? COMPONENT_BLOCK_PREMIUM
66	    : count * BASE_PREMIUM_RATES[type];
67	
68	const sumBasePremiums = (items: Item[]): number =>
69	  [...countByType(items)].reduce(
70	    (sum, [type, count]) => sum + basePremiumForType(type, count),
71	    0,
72	  );
73	
74	const quote = (items: Item[]): StepResult => {
75	  const basePremium = sumBasePremiums(items);
76	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
77	
78	  return {
79	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
80	  };
81	};
82	
83	const runStep = (step: Step): StepResult => {
84	  switch (step.op) {
85	    case "quote":
86	      return quote(step.items);
87	    default:
88	      throw new Error(`Unsupported step: ${step.op}`);
89	  }
90	};
91	
92	export const runScenario = (scenario: Scenario): ScenarioResult => ({
93	  results: scenario.steps.map(runStep),
94	});
